CREATE TABLE subjects (id UUID PRIMARY KEY, faculty_id VARCHAR(50) NOT NULL, code VARCHAR(50) NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uk_subject_faculty_code UNIQUE(faculty_id, code));
CREATE TABLE chapters (id UUID PRIMARY KEY, subject_id UUID NOT NULL REFERENCES subjects(id), code VARCHAR(50) NOT NULL, name VARCHAR(255) NOT NULL, ordinal_number INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uk_chapter_subject_code UNIQUE(subject_id, code));
CREATE TABLE topics (id UUID PRIMARY KEY, chapter_id UUID NOT NULL REFERENCES chapters(id), code VARCHAR(50) NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uk_topic_chapter_code UNIQUE(chapter_id, code));
CREATE TABLE questions (id UUID PRIMARY KEY, faculty_id VARCHAR(50) NOT NULL, subject_id UUID NOT NULL REFERENCES subjects(id), chapter_id UUID NOT NULL REFERENCES chapters(id), topic_id UUID REFERENCES topics(id), content TEXT NOT NULL, image_url VARCHAR(1000), storage_key VARCHAR(500), type VARCHAR(30) NOT NULL, difficulty VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, source VARCHAR(20) NOT NULL, ai_source_id VARCHAR(200) UNIQUE, created_by UUID NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT ck_question_type CHECK(type IN ('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE')), CONSTRAINT ck_question_difficulty CHECK(difficulty IN ('EASY','MEDIUM','HARD')), CONSTRAINT ck_question_status CHECK(status IN ('DRAFT','PENDING_REVIEW','APPROVED','NEED_REVISION','REJECTED','ARCHIVED')), CONSTRAINT ck_question_source CHECK(source IN ('MANUAL','AI')));
CREATE TABLE question_options (id UUID PRIMARY KEY, question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE, label VARCHAR(20) NOT NULL, content TEXT NOT NULL, image_url VARCHAR(1000), storage_key VARCHAR(500), is_correct BOOLEAN NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, CONSTRAINT uk_option_question_label UNIQUE(question_id,label));
CREATE TABLE question_review_history (id UUID PRIMARY KEY, question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE, reviewer_id UUID NOT NULL, action VARCHAR(30) NOT NULL, comment TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT ck_review_action CHECK(action IN ('APPROVED','REJECTED','REVISION_REQUESTED')));
CREATE TABLE processed_events (event_id UUID PRIMARY KEY, event_type VARCHAR(100) NOT NULL, processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_questions_faculty ON questions(faculty_id); CREATE INDEX idx_questions_catalog ON questions(subject_id,chapter_id,topic_id); CREATE INDEX idx_questions_filter ON questions(status,difficulty,source); CREATE INDEX idx_questions_creator ON questions(created_by); CREATE INDEX idx_review_question ON question_review_history(question_id,created_at);
